{
  "application": "poster-generation",
  "case_id": "case-tech-ai-aider-llm-polyglot-leaderboard-2025",
  "language": "en",
  "source_brief": "/app/benchmark/source_brief.md",
  "poster": {
    "aspect_ratio": "portrait",
    "audience": "data-report",
    "tone": "data-forward, modern",
    "venue": null
  },
  "brief": {
    "title": "Aider LLM Polyglot Coding Leaderboard 2025",
    "one_liner": "A data-driven comparison of top large language models ranked by their ability to autonomously write and edit code across six programming languages.",
    "goal": "The viewer should understand which LLMs perform best at autonomous code editing, how accuracy trades off against cost, and how different model families (OpenAI, Anthropic, Google, DeepSeek) compare on Aider's polyglot benchmark."
  },
  "sections": [
    {
      "id": "benchmark-overview",
      "title": "About the Benchmark",
      "objective": "Explain what the Aider polyglot benchmark measures: 225 Exercism coding exercises across C++, Go, Java, JavaScript, Python, and Rust, evaluated without human intervention."
    },
    {
      "id": "top-models-ranking",
      "title": "Top Models by Accuracy",
      "objective": "Present a ranked comparison of the highest-scoring models, highlighting the top 10 with their percent-correct scores and edit formats."
    },
    {
      "id": "cost-vs-accuracy",
      "title": "Cost vs. Accuracy Trade-Off",
      "objective": "Visualize or tabulate how model cost per run relates to accuracy, showing that the most accurate models are not always the most expensive."
    },
    {
      "id": "edit-format-quality",
      "title": "Edit Format Compliance",
      "objective": "Show how well each model follows the required edit format (correct edit format %), indicating reliability for automated workflows."
    },
    {
      "id": "key-takeaways",
      "title": "Key Takeaways",
      "objective": "Summarize the 3-4 most important insights: GPT-5 leads, cost varies dramatically, and several sub-$5 models still exceed 70% accuracy."
    }
  ],
  "metrics": [
    {
      "label": "Top Score",
      "value": "88.0%",
      "context": "GPT-5 (high reasoning effort)"
    },
    {
      "label": "Languages Tested",
      "value": "6",
      "context": "C++, Go, Java, JavaScript, Python, Rust"
    },
    {
      "label": "Total Exercises",
      "value": "225",
      "context": "Exercism coding challenges"
    },
    {
      "label": "Highest Cost Run",
      "value": "$29.08",
      "context": "GPT-5 (high)"
    },
    {
      "label": "Best Value Model",
      "value": "86.7% at $17.69",
      "context": "GPT-5 (medium) — nearly top accuracy at ~60% of the cost"
    },
    {
      "label": "Models Benchmarked",
      "value": "30+",
      "context": "Across OpenAI, Anthropic, Google, DeepSeek, and more"
    }
  ]
}

