      value 6
      desc C++, Go, Java, JS, Python, Rust
      icon globe
    - label Models Tested
      value 30+
      desc OpenAI, Anthropic, Google, DeepSeek
      icon cpu
theme
  palette #0EA5E9 #06B6D4 #F59E0B #3B82F6 #8B5CF6 #10B981
  base
    background #0B1120
    text font-family 851tegakasu
`;

infographic.render(syntax);

document.fonts?.ready.then(() => {
  infographic.render(syntax);
}).catch((e) => console.error(e));

setTimeout(async () => {
  try {
    const svgDataUrl = await infographic.toDataURL({ type: 'svg' });
    console.log('SVG data URL ready');
    const link = document.createElement('a');
    link.download = 'aider-llm-leaderboard-2025.svg';
    link.href = svgDataUrl;
    link.click();
  } catch(e) {
    console.error('Export error:', e);
  }
}, 2000);
</script>
</body>
</html>
