[metadata] {"type": "create", "filePath": "/app/output/aider-llm-leaderboard-2025.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Aider LLM Polyglot Coding Leaderboard 2025</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  :root {
    --bg-primary: #0B1120;
    --bg-secondary: #111827;
    --bg-card: #1E293B;
    --bg-card-hover: #273549;
    --accent-blue: #0EA5E9;
    --accent-teal: #06B6D4;
    --accent-amber: #F59E0B;
    --accent-green: #10B981;
    --accent-purple: #8B5CF6;
    --accent-red: #EF4444;
    --text-primary: #F8FAFC;
    --text-secondary: #94A3B8;
    --text-muted: #64748B;
    --border-color: #334155;
    --openai-color: #10B981;
    --anthropic-color: #F59E0B;
    --google-color: #0EA5E9;
    --deepseek-color: #8B5CF6;
    --other-color: #64748B;
  }

  body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    background: var(--bg-primary);
    color: var(--text-primary);
    width: 1080px;
    min-height: 1920px;
    overflow-x: hidden;
  }

  .poster-container {
    width: 1080px;
    min-height: 1920px;
    background: linear-gradient(180deg, #0B1120 0%, #0F172A 50%, #0B1120 100%);
    position: relative;
    overflow: hidden;
  }

  /* Grid background pattern */
  .poster-container::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background-image:
      linear-gradient(rgba(14,165,233,0.03) 1px, transparent 1px),
      linear-gradient(90deg, rgba(14,165,233,0.03) 1px, transparent 1px);
    background-size: 40px 40px;
    pointer-events: none;
  }

  /* Header */
  .header {
    padding: 48px 64px 32px;
    position: relative;
  }

  .header-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(14,165,233,0.1);
    border: 1px solid rgba(14,165,233,0.3);
    border-radius: 100px;
    padding: 6px 16px;
    font-size: 12px;
    font-weight: 600;
    color: var(--accent-blue);
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 20px;
  }

  .header h1 {
    font-size: 52px;
    font-weight: 900;
    line-height: 1.1;
    background: linear-gradient(135deg, #F8FAFC 0%, #94A3B8 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 12px;
  }

  .header-subtitle {
    font-size: 18px;
    color: var(--text-secondary);
    max-width: 700px;
    line-height: 1.6;
  }

  /* Hero Metrics */
  .hero-metrics {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    padding: 0 64px;
    margin-bottom: 40px;
  }

  .hero-metric {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 16px;
    padding: 24px;
    position: relative;
    overflow: hidden;
  }

  .hero-metric::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--accent-blue), var(--accent-teal));
  }

  .hero-metric:nth-child(2)::before {
    background: linear-gradient(90deg, var(--accent-amber), var(--accent-green));
  }

  .hero-metric:nth-child(3)::before {
    background: linear-gradient(90deg, var(--accent-purple), var(--accent-blue));
  }

  .hero-metric:nth-child(4)::before {
    background: linear-gradient(90deg, var(--accent-green), var(--accent-teal));
  }

  .hero-metric-value {
    font-family: 'JetBrains Mono', monospace;
    font-size: 42px;
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: 4px;
  }

  .hero-metric-label {
    font-size: 14px;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 4px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  .hero-metric-desc {
    font-size: 12px;
    color: var(--text-muted);
  }

  /* Section Title */
  .section-title {
    padding: 0 64px;
    margin-bottom: 20px;
  }

  .section-title h2 {
    font-size: 28px;
    font-weight: 800;
    color: var(--text-primary);
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .section-title h2::before {
    content: '';
    width: 4px;
    height: 28px;
    background: linear-gradient(180deg, var(--accent-blue), var(--accent-teal));
    border-radius: 2px;
  }

  /* Models Table */
  .models-section {
    padding: 0 64px;
    margin-bottom: 40px;
  }

  .models-table {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 16px;
    overflow: hidden;
  }

  .models-table-header {
    display: grid;
    grid-template-columns: 60px 1fr 100px 100px 100px 80px;
    padding: 16px 24px;
    background: rgba(14,165,233,0.05);
    border-bottom: 1px solid var(--border-color);
    font-size: 11px;
    font-weight: 700;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  .model-row {
    display: grid;
    grid-template-columns: 60px 1fr 100px 100px 100px 80px;
    padding: 14px 24px;
    align-items: center;
    border-bottom: 1px solid rgba(51,65,85,0.5);
    transition: background 0.15s;
  }

  .model-row:last-child {
    border-bottom: none;
  }

  .model-row:hover {
    background: var(--bg-card-hover);
  }

  .model-rank {
    font-family: 'JetBrains Mono', monospace;
    font-size: 16px;
    font-weight: 700;
    color: var(--text-muted);
  }

  .model-row:first-child .model-rank { color: #F59E0B; }
  .model-row:nth-child(2) .model-rank { color: #94A3B8; }
  .model-row:nth-child(3) .model-rank { color: #CD7F32; }

  .model-info {
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .model-badge {
    width: 10px;
    height: 10px;
    border-radius: 50%;
  }

  .model-badge.openai { background: var(--openai-color); box-shadow: 0 0 8px var(--openai-color); }
  .model-badge.anthropic { background: var(--anthropic-color); box-shadow: 0 0 8px var(--anthropic-color); }
  .model-badge.google { background: var(--google-color); box-shadow: 0 0 8px var(--google-color); }
  .model-badge.deepseek { background: var(--deepseek-color); box-shadow: 0 0 8px var(--deepseek-color); }
  .model-badge.other { background: var(--other-color); }

  .model-name {
    font-size: 14px;
    font-weight: 600;
    color: var(--text-primary);
  }

  .model-family {
    font-size: 11px;
    color: var(--text-muted);
    margin-top: 2px;
  }

  .model-score {
    font-family: 'JetBrains Mono', monospace;
    font-size: 16px;
    font-weight: 700;
  }

  .model-score.top { color: #10B981; }
  .model-score.high { color: #22C55E; }
  .model-score.mid { color: var(--accent-amber); }
  .model-score.low { color: var(--text-secondary); }

  .model-cost {
    font-family: 'JetBrains Mono', monospace;
    font-size: 14px;
    color: var(--text-secondary);
  }

  .model-cost-value {
    display: flex;
    align-items: center;
    gap: 4px;
  }

  .cost-bar {
    height: 6px;
    background: rgba(148,163,184,0.2);
    border-radius: 3px;
    margin-top: 6px;
    overflow: hidden;
  }

  .cost-bar-fill {
    height: 100%;
    border-radius: 3px;
    transition: width 0.3s;
  }

  .model-format {
    font-size: 12px;
    color: var(--text-muted);
    text-align: center;
  }

  .model-format-badge {
    display: inline-block;
    padding: 4px 8px;
    border-radius: 6px;
    font-size: 11px;
    font-weight: 600;
  }

  .format-diff { background: rgba(59,130,246,0.15); color: #60A5FA; }
  .format-fenced { background: rgba(16,185,129,0.15); color: #34D399; }

  /* Cost-Accuracy Section */
  .cost-section {
    padding: 0 64px;
    margin-bottom: 40px;
  }

  .cost-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
  }

  .cost-highlight-card {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 16px;
    padding: 28px;
    position: relative;
    overflow: hidden;
  }

  .cost-highlight-card.gold {
    border-color: rgba(245,158,11,0.3);
  }

  .cost-highlight-card.gold::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #F59E0B, #FBBF24);
  }

  .cost-highlight-card.value {
    border-color: rgba(16,185,129,0.3);
  }

  .cost-highlight-card.value::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #10B981, #34D399);
  }

  .cost-highlight-label {
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 12px;
  }

  .cost-highlight-card.gold .cost-highlight-label { color: var(--accent-amber); }
  .cost-highlight-card.value .cost-highlight-label { color: var(--accent-green); }

